המודלים: שיטת Duncan
מיון: M2 (5.33) · M1 (5.00) · M3 (3.99) · M5 (3.96) · M4 (3.76)

means &lt;- sort(tapply(calls$aht, calls$model, mean), decreasing = TRUE)
R_p   &lt;- setNames(r_duncan * sqrt(mse / 9), 2:5)

duncan &lt;- combn(names(means), 2, simplify = FALSE) |&gt;
  map(\(pair) {
    pos &lt;- match(pair, names(means))
    tibble(high = pair[1], low = pair[2], p = diff(pos) + 1,
           diff = means[pair[1]] - means[pair[2]], R_p = R_p[as.character(diff(pos) + 1)])
  }) |&gt;
  list_rbind() |&gt;
  mutate(significant = diff &gt; R_p) |&gt;
  arrange(desc(p))
